import React, { useState } from 'react';
import ReactMarkdown from 'react-markdown'; // 마크다운 렌더러 추가
import remarkGfm from 'remark-gfm'; // GFM 플러그인 추가
import './App.css';

function App() {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState([]);
  const [isStreaming, setIsStreaming] = useState(false);

  const sendMessage = async () => {
    if (!input.trim() || isStreaming) return;

    const userMsg = { role: 'user', content: input };
    // 사용자 메시지와 빈 응답 객체 추가
    setMessages(prev => [...prev, userMsg, { role: 'assistant', content: '' }]);
    setInput('');
    setIsStreaming(true);

    try {
      const response = await fetch('http://localhost:8000/chat/stream', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: input }),
      });

      const reader = response.body.getReader();
      const decoder = new TextDecoder("utf-8");
      let done = false;

      while (!done) {
        const { value, done: readerDone } = await reader.read();
        done = readerDone;

        if (value) {
          const chunk = decoder.decode(value, { stream: true });
          setMessages(prev => {
            const newMsgs = [...prev];
            const lastIdx = newMsgs.length - 1;
            newMsgs[lastIdx] = {
              ...newMsgs[lastIdx],
              content: newMsgs[lastIdx].content + chunk
            };
            return newMsgs;
          });
        }
      }
    } catch (error) {
      console.error("Gemini API Error:", error);
    } finally {
      setIsStreaming(false);
    }
  };

  return (
    <div className="chat-container">
      <header className="chat-header">Gemini Pro Chat</header>
      <div className="chat-window">
        {messages.map((msg, idx) => (
          <div key={idx} className={`message-bubble ${msg.role}`}>
            <div className="sender">{msg.role === 'user' ? '나' : 'Gemini'}</div>
            <div className="content">
              {/* Markdown 렌더링 적용 */}
              {msg.role === 'assistant' ? (
                <ReactMarkdown remarkPlugins={[remarkGfm]}>
                  {msg.content}
                </ReactMarkdown>
              ) : (
                msg.content
              )}
            </div>
          </div>
        ))}
        {isStreaming && <div className="streaming-indicator">입력 중...</div>}
      </div>
      <div className="input-area">
        <input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === 'Enter' && sendMessage()}
          placeholder="Gemini에게 질문하세요..."
          disabled={isStreaming}
        />
        <button onClick={sendMessage} disabled={isStreaming}>보내기</button>
      </div>
    </div>
  );
}

export default App;
